// Versioned recruitment drafts use existing club/event authority and shared command persistence.
function clubRecruitmentPlanReader(p){const c=p?.sourceClub&&clubById(p.sourceClub);return !!c&&canSee(p)&&(manageClub(c)||owner(p)&&clubMember(c)||uid===c.mentor||uid==='sa1')}
function clubRecruitmentPlanWritable(p){const c=p?.sourceClub&&clubById(p.sourceClub);return !!c&&clubRecruitmentPlanReader(p)&&(manageClub(c)||owner(p)&&clubMember(c))&&p.state==='APPROVED'&&!participantResolution(p,uid)&&clubRecruitmentAudience(p).available&&(!p.clubRecruitmentPlan||p.clubRecruitmentPlan.state==='DRAFT')}
function clubRecruitmentPlanLatest(p){return p?.clubRecruitmentPlan?.versions?.at(-1)||null}
function clubRecruitmentPlanPanel(p){if(!clubRecruitmentPlanReader(p))return '';const v=clubRecruitmentPlanLatest(p);return `<section class="panel"><h2>Volunteer domains & positions</h2><p>${p.clubRecruitmentPlan?.state==='OPEN'?'Positions frozen for club-member applications. Applications do not enrol participants or assign tasks.':'Draft planning only. Applications are not open; positions do not assign tasks, enrol participants or approve a budget.'}</p>${v?`<p>Draft version ${v.version} · ${esc(name(v.by))} · ${esc(eventTime(v.at))}</p>${tableHTML(['Task domain','Volunteer position','Capacity','Expected contribution'],v.positions.map(r=>[esc(r.domain),esc(r.title),r.capacity,esc(r.contribution)]))}<p>Total planned positions: ${v.positions.reduce((sum,r)=>sum+r.capacity,0)}. These are requested slots, not selected volunteers or approved event attendance.</p><details><summary>Draft version history</summary>${p.clubRecruitmentPlan.versions.map(r=>`<p>v${r.version} · ${esc(name(r.by))} · ${esc(eventTime(r.at))} · ${esc(r.reason)} · ${r.positions.length} position definition(s)</p>`).join('')}</details>`:'<p>No volunteer positions drafted yet.</p>'}${clubRecruitmentPlanWritable(p)?btn(v?'Revise position draft':'Draft domains & positions','clubRecruitmentPlanForm()'):''}<p>Initial audience remains the organizing club's active general members. Volunteer selection is reviewed separately; domain lead delegation remains pending.</p></section>`}
function clubRecruitmentPlanForm(){const p=current();if(!clubRecruitmentPlanWritable(p))return toast('Use a current approved club event and existing organizer authority.');const v=clubRecruitmentPlanLatest(p);modal(`<h2>Draft volunteer domains & positions</h2><p>Define up to 10 position types for this prototype draft. Reuse a domain for several positions. All capacities are planning requests; no recruitment opens on save.</p><form onsubmit="saveClubRecruitmentPlan(event,${v?.version||0})">${Array.from({length:10},(_,i)=>{const r=v?.positions[i];return `<details ${i===0||r?'open':''}><summary>Position ${i+1}${r?' · '+esc(r.title):' (optional)'}</summary><label>Task domain<input name="domain${i}" maxlength="80" value="${esc(r?.domain||'')}"></label><label>Position title<input name="position${i}" maxlength="80" value="${esc(r?.title||'')}"></label><label>Number of volunteers<input name="capacity${i}" type="number" min="1" max="999" step="1" value="${r?.capacity||''}"></label><label>Expected contribution<textarea name="contribution${i}" maxlength="500">${esc(r?.contribution||'')}</textarea></label></details>`}).join('')}<label>Reason for this draft/revision<textarea name="reason" required maxlength="1000"></textarea></label><button type="submit" class="primary">Save position draft</button><button type="button" onclick="closeModal()">Cancel</button></form>`)}
function saveClubRecruitmentPlan(event,expectedVersion){event.preventDefault();const p=current();if(!clubRecruitmentPlanWritable(p))return toast('Current approved club event and organizer authority required.');const prior=p.clubRecruitmentPlan,latest=clubRecruitmentPlanLatest(p);if(!Number.isSafeInteger(expectedVersion)||expectedVersion<0||expectedVersion!==(latest?.version||0))return toast('Position draft changed. Refresh and review before saving.');const f=Object.fromEntries(new FormData(event.target)),text=v=>typeof v==='string'?v.trim():'',positions=[],seen=new Set();
 const keys=['reason',...Array.from({length:10},(_,i)=>['domain','position','capacity','contribution'].map(k=>k+i)).flat()];if(Object.keys(f).some(k=>!keys.includes(k)))return toast('Unexpected position field.');
 for(let i=0;i<10;i++){const domain=text(f['domain'+i]),title=text(f['position'+i]),raw=text(f['capacity'+i]),contribution=text(f['contribution'+i]);if(!domain&&!title&&!raw&&!contribution)continue;if(!domain||domain.length>80||!title||title.length>80||!contribution||contribution.length>500||!/^\d{1,3}$/.test(raw)||Number(raw)<1||/[\u0000-\u001f]/.test(domain+title))return toast('Complete each used row: domain, title, capacity 1–999 and expected contribution.');const key=domain.normalize('NFKC').toLowerCase()+'\u0000'+title.normalize('NFKC').toLowerCase();if(seen.has(key))return toast('Use a unique position title within each task domain.');seen.add(key);positions.push({id:'VP'+(expectedVersion+1)+'-'+i,domain,title,capacity:Number(raw),contribution})}
 const reason=text(f.reason);if(!positions.length||!reason||reason.length>1000)return toast('Add at least one complete position and a revision reason.');const c=clubById(p.sourceClub),plan=clubPlan(c,p.clubPlanId),v={version:expectedVersion+1,positions,reason,by:uid,at:new Date().toISOString(),source:{clubId:c.id,planId:plan.id,planVersion:plan.version||1,itemId:p.clubPlanItem,eventOwner:p.owner,mentor:p.mentor}};p.clubRecruitmentPlan={state:'DRAFT',versions:[...(prior?.versions||[]),v]};log(p,'Volunteer position draft saved v'+v.version);closeModal();render();toast('Position draft saved. Applications remain closed.')}
const clubRecruitmentPlanPreviousOverview=projectOverview;projectOverview=function(p){return clubRecruitmentPlanPreviousOverview(p)+clubRecruitmentPlanPanel(p)};
